import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnAoeServe, appDirFor, fakeAcpScriptPath } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/aoeServe.ts';
import { startAcpSession, postPrompt, replayFrames } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/acp.ts';
const [binary] = process.argv.slice(2);
assert(binary?.startsWith('/'));
process.env.AOE_E2E_BINARY = binary;
const until = async (predicate, label, milliseconds = 30000) => {
  const deadline = Date.now() + milliseconds;
  for (;;) {
    const value = await predicate();
    if (value) return value;
    assert(Date.now() < deadline, `observable deadline: ${label}`);
    await new Promise(resolve => setTimeout(resolve, 25));
  }
};
let serve;
try {
  const initial = await startAcpSession(async options => {
    serve = await spawnAoeServe({ ...options, workerIndex: 0, parallelIndex: 37 });
    return serve;
  }, { title: 'B explicit ACP restart', fakeAcpScript: { turns: [{ updates: [{ sessionUpdate: 'agent_message_chunk', content: { type: 'text', text: 'ORIGINAL_RESTART_HISTORY' } }], stopReason: 'end_turn' }] } });
  const id = initial.sessionId;
  const frames = () => replayFrames(serve.baseUrl, id);
  const row = async () => {
    const body = await fetch(`${serve.baseUrl}/api/sessions`).then(response => response.json());
    return (Array.isArray(body) ? body : body.sessions).find(value => value.id === id);
  };
  const log = () => readFileSync(`${serve.home}/fake-acp.log`, 'utf8');
  const nativePids = () => [...log().matchAll(/fake-acp starting pid=(\d+) argv=(.*)/g)].filter(match => !JSON.parse(match[2]).includes('--version')).map(match => Number(match[1]));
  const registry = () => {
    const value = JSON.parse(readFileSync(`${appDirFor(serve.home, serve.env.XDG_CONFIG_HOME, binary)}/acp-workers/${id}.json`, 'utf8'));
    return { pid: value.pid, generation: value.generation, birth: value.runner_identity, agentName: value.agent_name, cwd: value.cwd };
  };
  const sid = await until(async () => (await frames()).find(frame => frame.event?.AcpSessionAssigned)?.event.AcpSessionAssigned.acp_session_id, 'original native assignment');
  await until(async () => (await row()).acp_session_id === sid, 'original durable SID');
  assert((await postPrompt(serve.baseUrl, id, 'FIRST_EXPLICIT_INPUT')).ok);
  await until(async () => (await frames()).some(frame => frame.event?.Stopped?.reason === 'prompt_complete'), 'first actual turn complete');
  const oldFrames = await frames();
  assert(JSON.stringify(oldFrames).includes('ORIGINAL_RESTART_HISTORY'));
  const oldRow = await row();
  const oldOwner = registry();
  const oldNativePids = nativePids();
  assert.equal(oldNativePids.length, 1);
  writeFileSync(fakeAcpScriptPath(serve.home), JSON.stringify({ turns: [{ updates: [{ sessionUpdate: 'agent_message_chunk', content: { type: 'text', text: 'AFTER_EXPLICIT_RESTART_INPUT' } }], stopReason: 'end_turn' }] }));
  const response = await fetch(`${serve.baseUrl}/api/sessions/${id}/acp/restart`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' });
  const responseBody = await response.text();
  assert.equal(response.status, 200, responseBody);
  await until(async () => nativePids().length === 2 && (await row()).acp_session_id === sid && (await frames()).filter(frame => frame.event?.AcpSessionAssigned?.acp_session_id === sid).length >= 2, 'new original-SID runtime ready');
  const newOwner = registry();
  assert.notDeepEqual(newOwner, oldOwner);
  assert.equal([...log().matchAll(/handleRequest method=session\/new id=/g)].length, 1);
  assert.equal([...log().matchAll(/handleRequest method=session\/load id=/g)].length, 1);
  assert.equal([...log().matchAll(/handleRequest method=session\/prompt id=/g)].length, 1, 'restart must not replay input');
  const newRow = await row();
  assert.equal(typeof oldOwner.agentName, 'string', 'fixture requires the native registry agent');
  assert.equal(newOwner.agentName, oldOwner.agentName);
  assert.equal(oldOwner.cwd, oldRow.project_path);
  assert.equal(newOwner.cwd, oldOwner.cwd);
  for (const field of ['project_path', 'tool']) {
    assert.equal(typeof oldRow[field], 'string', `fixture requires ${field}`);
    assert.equal(newRow[field], oldRow[field]);
  }
  const afterRestart = await frames();
  for (const prior of oldFrames) assert(afterRestart.some(frame => frame.seq === prior.seq && JSON.stringify(frame.event) === JSON.stringify(prior.event)), `history lost at ${prior.seq}`);
  const frontier = Math.max(...afterRestart.map(frame => frame.seq));
  assert((await postPrompt(serve.baseUrl, id, 'SECOND_EXPLICIT_INPUT')).ok);
  await until(async () => (await frames()).some(frame => frame.seq > frontier && frame.event?.Stopped?.reason === 'prompt_complete'), 'second actual turn complete');
  const finalFrames = await frames();
  assert(JSON.stringify(finalFrames).includes('AFTER_EXPLICIT_RESTART_INPUT'));
  assert.deepEqual(registry(), newOwner);
  assert.equal((await row()).acp_session_id, sid);
  assert.equal([...log().matchAll(/handleRequest method=session\/new id=/g)].length, 1);
  assert.equal([...log().matchAll(/handleRequest method=session\/load id=/g)].length, 1);
  assert.equal([...log().matchAll(/handleRequest method=session\/prompt id=/g)].length, 2);
  console.log('B_EXPLICIT_ACP_RESTART_GREEN', JSON.stringify({ id, sid, oldOwner, newOwner, oldNativePids, newNativePids: nativePids(), restartHttp: response.status, responseBody, nativeNew: 1, nativeLoad: 1, explicitPrompts: 2, implicitReplay: 0, historyPreserved: true, finalFrames, nativeLog: log(), limits: 'Actual daemon/private runner/native fake peer. Full original binding checkpoint window is separately exercised by the real-peer in-module regression; this smoke does not invent a pending-binding race or external-provider result.' }));
} finally {
  if (serve) await serve.stop();
  console.log('B_EXPLICIT_ACP_RESTART_CLEANUP_GREEN');
}
